<template>
  <div class="art-full-height">
    <ElCard class="mb-3"><ElForm inline><ElFormItem label="任务号"><ElInput v-model="query.taskNo" clearable/></ElFormItem><ElFormItem label="派单模式"><ElSelect v-model="query.dispatchMode" clearable class="!w-32"><ElOption label="指定派单" value="DIRECT"/><ElOption label="抢单" value="GRAB"/></ElSelect></ElFormItem><ElFormItem label="任务状态"><ElSelect v-model="query.taskStatus" clearable class="!w-32"><ElOption v-for="(x,k) in statusMeta" :key="k" :label="x.text" :value="k"/></ElSelect></ElFormItem><ElFormItem><ElButton @click="reset">重置</ElButton><ElButton type="primary" @click="search">查询</ElButton></ElFormItem></ElForm></ElCard>
    <ElCard class="art-table-card"><ArtTableHeader :loading="loading" @refresh="load"/><ElTable v-loading="loading" :data="rows"><ElTableColumn prop="taskNo" label="派单任务号" min-width="185"/><ElTableColumn prop="orderNo" label="订单号" min-width="185"/><ElTableColumn label="模式" width="95"><template #default="{row}"><ElTag>{{row.dispatchMode==='DIRECT'?'指定派单':'公开抢单'}}</ElTag></template></ElTableColumn><ElTableColumn prop="attemptNo" label="轮次" width="70"/><ElTableColumn prop="candidateCount" label="候选人数" width="85"/><ElTableColumn prop="acceptedPlayerName" label="接单陪玩师" min-width="120"><template #default="{row}">{{row.acceptedPlayerName||'-'}}</template></ElTableColumn><ElTableColumn label="截止时间" min-width="165"><template #default="{row}">{{formatDateTime(row.deadlineAt)}}</template></ElTableColumn><ElTableColumn label="状态" width="95"><template #default="{row}"><ElTag :type="statusMeta[row.taskStatus]?.type">{{statusMeta[row.taskStatus]?.text||row.taskStatus}}</ElTag></template></ElTableColumn><ElTableColumn label="操作" width="80" fixed="right"><template #default="{row}"><ArtButtonMore :list="actions(row)" @click="i=>action(i.key,row)"/></template></ElTableColumn></ElTable><div class="flex justify-end mt-4"><ElPagination v-model:current-page="query.current" v-model:page-size="query.size" :total="total" layout="total, sizes, prev, pager, next" @change="load"/></div></ElCard>
    <ElDrawer v-model="detailVisible" title="派单任务详情" size="720px"><template v-if="detail"><ElDescriptions :column="2" border><ElDescriptionsItem label="任务号">{{detail.taskNo}}</ElDescriptionsItem><ElDescriptionsItem label="订单号">{{detail.orderNo}}</ElDescriptionsItem><ElDescriptionsItem label="模式">{{detail.dispatchMode==='DIRECT'?'指定派单':'公开抢单'}}</ElDescriptionsItem><ElDescriptionsItem label="状态">{{statusMeta[detail.taskStatus]?.text}}</ElDescriptionsItem><ElDescriptionsItem label="截止时间">{{formatDateTime(detail.deadlineAt)}}</ElDescriptionsItem><ElDescriptionsItem label="接单人">{{detail.acceptedPlayerName||'-'}}</ElDescriptionsItem></ElDescriptions><h4 class="my-4">候选陪玩师</h4><ElTable :data="detail.candidates" border><ElTableColumn label="陪玩师" min-width="150"><template #default="{row}">{{row.playerName}}（{{row.playerNo}}）</template></ElTableColumn><ElTableColumn prop="ratingScore" label="评分" width="70"/><ElTableColumn prop="activeOrderCount" label="进行中" width="75"/><ElTableColumn prop="matchScore" label="匹配分" width="85"/><ElTableColumn label="响应" width="85"><template #default="{row}">{{candidateText[row.candidateStatus]||row.candidateStatus}}</template></ElTableColumn><ElTableColumn v-if="detail.taskStatus==='DISPATCHING'&&has('business:dispatch:respond')" label="模拟操作" width="130"><template #default="{row}"><template v-if="row.candidateStatus==='PENDING'"><ElButton link type="primary" @click="respond(row,'ACCEPT')">接受</ElButton><ElButton link type="danger" @click="respond(row,'REJECT')">拒绝</ElButton></template></template></ElTableColumn></ElTable><h4 class="my-4">派单记录</h4><ElTimeline><ElTimelineItem v-for="x in detail.logs" :key="x.id" :timestamp="formatDateTime(x.createTime)"><div>{{actionText[x.actionType]||x.actionType}} <span v-if="x.playerName">· {{x.playerName}}</span></div><small>{{x.operatorName||'系统'}}{{x.reason?` · ${x.reason}`:''}}</small></ElTimelineItem></ElTimeline></template></ElDrawer>
    <ElDialog v-model="retryVisible" title="重新派单" width="680px"><ElForm label-width="90px"><ElFormItem label="派单模式"><ElRadioGroup v-model="retryForm.dispatchMode"><ElRadioButton value="DIRECT">指定派单</ElRadioButton><ElRadioButton value="GRAB">公开抢单</ElRadioButton></ElRadioGroup></ElFormItem></ElForm><ElTable :data="eligible" border><ElTableColumn prop="playerName" label="陪玩师"/><ElTableColumn prop="ratingScore" label="评分" width="70"/><ElTableColumn prop="matchScore" label="匹配分" width="85"/><ElTableColumn v-if="retryForm.dispatchMode==='DIRECT'" label="选择" width="65"><template #default="{row}"><ElRadio v-model="retryForm.targetPlayerId" :value="row.playerId"><span/></ElRadio></template></ElTableColumn></ElTable><template #footer><ElButton @click="retryVisible=false">取消</ElButton><ElButton type="primary" @click="saveRetry">发起派单</ElButton></template></ElDialog>
  </div>
</template>
<script setup lang="ts">
import ArtButtonMore from'@/components/core/forms/art-button-more/index.vue';import{fetchDispatches,fetchDispatch,respondDispatch,cancelDispatch,fetchEligiblePlayers,createDispatch}from'@/api/business-manage';import{useUserStore}from'@/store/modules/user';import{formatDateTime}from'@/utils/date';const store=useUserStore(),has=(c:string)=>store.info.roles?.includes('admin')||store.info.buttons?.includes(c),loading=ref(false),rows=ref<Api.Business.DispatchTask[]>([]),total=ref(0),detailVisible=ref(false),retryVisible=ref(false),detail=ref<Api.Business.DispatchTask>(),eligible=ref<Api.Business.DispatchCandidate[]>([]),retryTask=ref<any>(),query=reactive<any>({current:1,size:20,taskNo:'',dispatchMode:'',taskStatus:''}),retryForm=reactive<any>({});const statusMeta:any={DISPATCHING:{text:'派单中',type:'primary'},PARTIAL:{text:'部分接单',type:'warning'},ACCEPTED:{text:'成员已满',type:'success'},REJECTED:{text:'全部拒绝',type:'warning'},EXPIRED:{text:'已超时',type:'warning'},CANCELLED:{text:'已取消',type:'info'}},candidateText:any={PENDING:'待响应',ACCEPTED:'已接受',REJECTED:'已拒绝',CLOSED:'已关闭',TIMEOUT:'已超时'},actionText:any={CREATE:'发起派单',ACCEPT:'接受',REJECT:'拒绝',CLOSE:'结束任务',EXPIRE:'任务超时',CANCEL:'取消任务'};async function load(){loading.value=true;try{const d=await fetchDispatches(query);rows.value=d.records;total.value=d.total}finally{loading.value=false}}function search(){query.current=1;load()}function reset(){Object.assign(query,{current:1,taskNo:'',dispatchMode:'',taskStatus:''});load()}function actions(row:any){return[{key:'detail',label:'查看详情',icon:'ri:eye-line'},...(has('business:dispatch:cancel')&&row.taskStatus==='DISPATCHING'?[{key:'cancel',label:'取消任务',icon:'ri:close-circle-line',color:'#f56c6c'}]:[]),...(has('business:dispatch:create')&&['PARTIAL','REJECTED','EXPIRED','CANCELLED'].includes(row.taskStatus)&&row.orderStatus==='WAIT_ASSIGN'?[{key:'retry',label:row.taskStatus==='PARTIAL'?'继续派单':'重新派单',icon:'ri:restart-line'}]:[])]}async function action(key:string|number,row:any){if(key==='detail'){detail.value=await fetchDispatch(row.id);detailVisible.value=true}else if(key==='cancel'){const reason=await ElMessageBox.prompt('请输入取消原因','取消派单',{inputValidator:v=>Boolean(v)||'请输入取消原因'}).then(x=>x.value);await cancelDispatch(row.id,reason);load()}else{retryTask.value=row;eligible.value=await fetchEligiblePlayers(row.orderId);Object.assign(retryForm,{dispatchMode:'DIRECT',targetPlayerId:undefined});retryVisible.value=true}}async function respond(row:any,action:string){let reason='';if(action==='REJECT')reason=await ElMessageBox.prompt('请输入拒绝原因','模拟拒单',{inputValidator:v=>Boolean(v)||'请输入拒绝原因'}).then(x=>x.value);else await ElMessageBox.confirm(`确定模拟“${row.playerName}”接受该订单吗？`,'模拟接单');await respondDispatch(detail.value!.id,row.playerId,action,reason);detail.value=await fetchDispatch(detail.value!.id);load()}async function saveRetry(){if(retryForm.dispatchMode==='DIRECT'&&!retryForm.targetPlayerId)return ElMessage.warning('请选择陪玩师');await createDispatch({orderId:retryTask.value.orderId,dispatchMode:retryForm.dispatchMode,targetPlayerId:retryForm.dispatchMode==='DIRECT'?retryForm.targetPlayerId:null});retryVisible.value=false;ElMessage.success(retryTask.value.taskStatus==='PARTIAL'?'已继续发起派单':'已重新发起派单');load()}onMounted(load)
</script>
